            const Vec rc = v3(r.x < lo.x ? lo.x : r.x > hi.x ? hi.x : r.x, r.y < lo.y ? lo.y : r.y > hi.y ? hi.y : r.y, r.z < lo.z ? lo.z : r.z > hi.z ? hi.z : r.z);
