                        dC[j]+=dec*_mm512_reduce_add_ps(_mm512_mul_ps(hv,vdR));
                        const __m512 dht=_mm512_fmadd_ps(_mm512_set1_ps(C[j]),vdR,lv);
                        vdec=_mm512_fmadd_ps(dht,hv,vdec);
