                        real*dZ=dpt+2*G*n+pv;ddt[tr]+=da;
                        for(int q=0;q<pv;q++){real gq=0;for(int j=0;j<n;j++)gq+=C[j]*hq[j*pv+q];dZ[q]+=da*gq;const real dg=da*Zv[q];
                            for(int j=0;j<n;j++){dC[j]+=dg*hq[j*pv+q];la[j*pv+q]+=C[j]*dg;}}
