static void mm_reset(const unsigned char*buf){mmx_reset(&mm,buf,0);}
static uint32_t mm_hash(const unsigned char*x,int bits){uint32_t h=2166136261u;for(int k=0;k<MM_MIN;k++)h=(h^x[k])*16777619u;return h>>(32-bits);}
